{"content":"import ast
import json
import pathlib
import re
import sys

ROOT = pathlib.Path("/private/var/folders/w_/swqg2n117dzdrptxy6074cqw0000gp/T/w/b9995e5c8704")
LFS_FIRST = "version https://git-lfs.github.com/spec/v1"
HEX64 = re.compile(r"^[0-9a-f]{64}$")


def load_cfg(d):
    try:
        return json.loads((d / "config.json").read_text())
    except Exception:
        return {}


def is_lfs_pointer(p):
    try:
        lines = p.read_text(errors="replace").splitlines()
    except Exception:
        return False
    return bool(lines) and lines[0].strip() == LFS_FIRST


def py_files(d):
    return sorted(p for p in (d / "src").rglob("*.py") if p.is_file())


def docker_from_ok(dockerfile_text):
    """Return list of (lineno, ok) for each FROM line."""
    out = []
    for i, line in enumerate(dockerfile_text.splitlines(), 1):
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        parts = s.split()
        if parts[0].upper() != "FROM":
            continue
        rest = parts[1:]
        while rest and rest[0].startswith("--"):
            rest = rest[1:]
        if not rest:
            out.append((i, False))
            continue
        image = rest[0]
        ok = False
        if "@sha256:" in image:
            digest = image.rsplit("@sha256:", 1)[1]
            ok = bool(HEX64.match(digest))
        out.append((i, ok))
    return out


def last_user(dockerfile_text):
    user = None
    for line in dockerfile_text.splitlines():
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        parts = s.split()
        if parts[0].upper() == "USER" and len(parts) > 1:
            user = parts[1]
    return user


def codeowners_star_ok(text, team):
    for line in text.splitlines():
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        toks = s.split()
        if toks and toks[0] == "*":
            if f"@team-{team}" in toks[1:]:
                return True
    return False


def req_line_ok(line):
    s = line.strip()
    if not s or s.startswith("#"):
        return True
    # strip an inline comment introduced by whitespace + '#'
    s = re.split(r"\s+#", s, 1)[0].strip()
    if not s:
        return True
    if ";" in s:
        s = s.split(";", 1)[0].strip()
    m = re.match(r"^[A-Za-z0-9][A-Za-z0-9._-]*(\[[A-Za-z0-9,._-]+\])?\s*==\s*([A-Za-z0-9][A-Za-z0-9.+!_-]*)$", s)
    return bool(m)


def string_literals(tree):
    out = []
    for n in ast.walk(tree):
        if isinstance(n, ast.Constant) and isinstance(n.value, str):
            out.append(n.value)
        elif isinstance(n, ast.JoinedStr):
            for part in n.values:
                if isinstance(part, ast.Constant) and isinstance(part.value, str):
                    out.append(part.value)
    return out


def print_calls(tree):
    out = []
    for n in ast.walk(tree):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id == "print":
            out.append(n.lineno)
    return out


def health_segment(cfg):
    hc = cfg.get("healthcheck")
    if isinstance(hc, str):
        path = hc
    elif isinstance(hc, dict):
        path = hc.get("path", "")
    else:
        return None
    path = path.split("?")[0].rstrip("/")
    if not path:
        return None
    return path.rsplit("/", 1)[-1]


def audit(d):
    cfg = load_cfg(d)
    v = []
    details = {}
    public = cfg.get("exposure") == "public"
    name = d.name

    # C1
    if public:
        t = cfg.get("timeout_s")
        if not (isinstance(t, (int, float)) and not isinstance(t, bool) and t <= 30):
            v.append("C1")
            details["C1"] = t

    # C2
    hp = d / "src/handlers.py"
    c2ok = True
    try:
        tree = ast.parse(hp.read_text())
        for n in ast.walk(tree):
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n.name.startswith("handle_"):
                if ast.get_docstring(n) is None:
                    c2ok = False
                    details.setdefault("C2", []).append(n.name)
    except Exception as e:
        c2ok = False
        details["C2"] = f"parse error: {e}"
    if not c2ok:
        v.append("C2")

    # C3
    c3 = []
    for p in py_files(d):
        try:
            t = ast.parse(p.read_text())
        except Exception as e:
            c3.append(f"{p}: parse error {e}")
            continue
        for ln in print_calls(t):
            c3.append(f"{p.relative_to(d)}:{ln}")
    if c3:
        v.append("C3")
        details["C3"] = c3

    # C4
    r = cfg.get("retries")
    if not (type(r) is int and 1 <= r <= 5):
        v.append("C4")
        details["C4"] = r

    # C5
    df = (d / "Dockerfile").read_text()
    bad_from = [i for i, ok in docker_from_ok(df) if not ok]
    if bad_from or not docker_from_ok(df):
        v.append("C5")
        details["C5"] = bad_from or "no FROM"

    # C6
    u = last_user(df)
    if u is None or u.split(":", 1)[0] in ("root", "0"):
        v.append("C6")
        details["C6"] = u

    # C7
    if "## Runbook" not in (d / "README.md").read_text().splitlines():
        v.append("C7")

    # C8
    if not codeowners_star_ok((d / "CODEOWNERS").read_text(), str(cfg.get("team"))):
        v.append("C8")
        details["C8"] = cfg.get("team")

    # C9
    c9 = []
    for p in py_files(d):
        try:
            t = ast.parse(p.read_text())
        except Exception as e:
            c9.append(f"{p}: parse error {e}")
            continue
        for lit in string_literals(t):
            if lit.startswith("sk_live_") or lit.startswith("AKIA"):
                c9.append(f"{p.relative_to(d)}: {lit[:24]}")
    if c9:
        v.append("C9")
        details["C9"] = c9

    # C10
    seg = health_segment(cfg)
    ok10 = seg is not None
    if ok10:
        try:
            t = ast.parse(hp.read_text())
            names = {n.name for n in ast.walk(t) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))}
            ok10 = f"handle_{seg}" in names
        except Exception:
            ok10 = False
    if not ok10:
        v.append("C10")
        details["C10"] = {"healthcheck": cfg.get("healthcheck"), "segment": seg}

    # C11
    if cfg.get("metrics_port") == cfg.get("port"):
        v.append("C11")

    # C12
    bad_req = []
    for i, line in enumerate((d / "requirements.txt").read_text().splitlines(), 1):
        if not req_line_ok(line):
            bad_req.append(f"{i}: {line.strip()}")
    if bad_req:
        v.append("C12")
        details["C12"] = bad_req

    # C13
    if cfg.get("log_level") == "DEBUG":
        v.append("C13")

    # C14
    if public:
        mb = cfg.get("max_body_kb")
        if not (isinstance(mb, (int, float)) and not isinstance(mb, bool) and mb <= 1024):
            v.append("C14")
            details["C14"] = mb

    # C15
    tests = d / "tests"
    if not any(p.is_file() and p.match("test_*.py") for p in tests.rglob("*")) if tests.is_dir() else True:
        v.append("C15")

    ptrs = [str(p.relative_to(d)) for p in sorted(d.rglob("*")) if p.is_file() and is_lfs_pointer(p)]
    return v, details, ptrs, cfg


def main():
    services = sorted([p for p in (ROOT / "services").iterdir() if p.is_dir()])
    results = {}
    for d in services:
        v, details, ptrs, cfg = audit(d)
        if ptrs:
            results[d.name] = {"service": d.name, "status": "unverifiable", "violations": [], "_pointers": ptrs}
        else:
            results[d.name] = {
                "service": d.name,
                "status": "violations" if v else "compliant",
                "violations": v,
                "_details": details,
            }
        print(d.name, results[d.name]["status"], v, "| pointers:", ptrs if ptrs else "")
        for k, val in details.items():
            print("    ", k, val)
    if len(sys.argv) > 1 and sys.argv[1] == "write":
        out = ROOT / "findings"
        out.mkdir(exist_ok=True)
        for name, r in results.items():
            payload = {k: r[k] for k in ("service", "status", "violations")}
            (out / f"{name}.json").write_text(json.dumps(payload) + "\n")
        print("WROTE", len(results))


main()
