        problems.append(f"{f.name}: duplicates {v}")
    if st == "compliant" and v:
        problems.append(f"{f.name}: compliant with violations")
    if st == "violations" and not v:
        problems.append(f"{f.name}: violations status with empty list")
    if st == "unverifiable" and v:
        problems.append(f"{f.name}: unverifiable with violations")
    if not raw.endswith("\n") or "\n" in raw.strip():
        problems.append(f"{f.name}: not single line")

# 2. independent line-based cross-check of structural clauses
def pfirst(p):
